18:     return ({
19:     id: mappingShapeId(`grid:${box.box.id}`), type: 'mapping-box',
20:     x: (box.bounds.column - (parent?.bounds.column ?? 0)) * cell.width, y: (box.bounds.row - (parent?.bounds.row ?? 0)) * cell.height,
21:     ...(parent ? { parentId: mappingShapeId(`grid:${parent.box.id}`) } : {}),
22:     isLocked: box.box.kind === 'container' && box.box.id === document.scene.root.id,
23:     props: { nodeId: `grid:${box.box.id}`, kind: box.box.kind, revisionId: box.contentId ? document.scene.contents[box.contentId].revisionId : '',
24:       w: Math.max(1, box.bounds.columns * cell.width), h: Math.max(1, box.bounds.rows * cell.height) },
25:   }); });
