76:       this.requested = key;
77:       this.pending = { id: ++this.serial, key, inputs, obstacles };
78:       this.dispatch();
79:     }
80:     return this.preview(inputs);
81:   }
82:   private preview(inputs: readonly RoutingInput[]) {
83:     return new Map(inputs.map(([edge, source, target, , , geometry]) => [edge.id,
84:       previewEdge(edge, source, target, this.settled.get(edge.id), geometry)]));
85:   }
86:   private dispatch() {
87:     if (this.inFlight || !this.pending || !this.createWorker) return;
88:     try {
89:       if (!this.worker) {
90:         const worker = this.worker = this.createWorker();
91:         worker.onmessage = (event: MessageEvent<{ id: number; arrows: Map<string, FloatingBoxArrow>; error?: string }>) => {
92:           if (this.worker !== worker || event.data.id !== this.inFlight?.id) return;
93:           if (event.data.error) { this.failWorker(); return; }
94:           const job = this.inFlight; this.inFlight = undefined;
95:           // A worker can finish after newer geometry is requested. Never publish
96:           // that stale result; retain only the newest pending request.
97:           if (job.key === this.requested) this.completed.set({ key: job.key, arrows: event.data.arrows });
98:           this.dispatch();
99:         };
100:         worker.onerror = () => { if (this.worker === worker) this.failWorker(); };
101:       }
102:       const job = this.inFlight = this.pending; this.pending = undefined;
103:       this.worker.postMessage({ id: job.id, inputs: job.inputs, obstacles: job.obstacles });
104:     } catch { this.failWorker(); }
105:   }
106:   private failWorker() {
107:     this.worker?.terminate(); this.worker = undefined; this.createWorker = undefined;
108:     this.inFlight = this.pending = undefined; this.requested = undefined;
109:     // Publish on a later task: construction/postMessage can fail while a
110:     // computed read is running, where reactive writes are not allowed.
111:     queueMicrotask(() => this.completed.set({ key: 'worker-failed', arrows: new Map() }));
112:   }
113:   dispose() {
114:     this.worker?.terminate(); this.worker = undefined; this.inFlight = this.pending = undefined;
115:     this.requested = undefined; this.completed.set(undefined); this.settled = new Map();
116:   }
117:   draw(...input: RoutingInput) { return this.router.draw(input, this.obstacles.get()); }
118: }
